void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Map<String, Integer> nodeFreq = new HashMap<String, Integer>();
    Map<String, Double> nodeScore = new HashMap<String, Double>();
    Map<String, List<String>> nodeConnected = new HashMap<String, List<String>>();
    Set<String> allNodes = new HashSet<String>();

    for (Map<String, V> cluster : resultMap.values()) {
        for (String node : cluster.keySet()) {
            nodeFreq.put(node, nodeFreq.getOrDefault(node, 0) + 1);
            nodeScore.put(node, nodeScore.getOrDefault(node, 0.0) + cluster.size());
            nodeConnected.put(node, new ArrayList<String>());
            allNodes.add(node);
        }
    }

    for (Map<String, V> cluster : resultMap.values()) {
        for (String node : cluster.keySet()) {
            for (String otherNode : cluster.keySet()) {
                if (otherNode.compareTo(node) <= 0) {
                    continue;
                }
                String edgeLabel = node + "-" + otherNode + "-" + cluster.hashCode();
                allNodes.add(edgeLabel);
                nodeConnected.get(node).add(edgeLabel);
                nodeConnected.get(otherNode).add(edgeLabel);
            }
        }
    }

    for (String node : allNodes) {
        if (!nodeConnected.containsKey(node)) {
            continue;
        }
        for (String neighbor : nodeConnected.get(node)) {
            target.addEdge(node, neighbor);
        }
    }
}

void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new NullPointerException("Unable to generate graph: target or resultMap is null.");
    }

    // Initialize the number of vertices for the graph
    int numVertices = Math.max(2, resultMap.size());

    // Create the bipartite graph
    BipartiteGraph<V, E> graph = new BipartiteGraph<>(target, numVertices);

    // Create the vertices for the graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        graph.addVertex(vertex);
    }

    // Connect the vertices with edges
    for (V vertex : graph.getVertices()) {
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            if (entry.getValue().equals(vertex)) {
                continue;
            }
            graph.addEdge(vertex, entry.getValue());
        }
    }

    return graph;
}

