    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<Class<?>>[] typeParameters = targetType.getTypeParameters();
        Map<TypeVariable<Class<?>>, Type> mappings = new HashMap<>();
        for (int i = 0; i < typeArguments.length; i++) {
            mappings.put(typeParameters[i], typeArguments[i]);
        }
        Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            resolvedArguments[i] = resolveTypeVariable(targetType, mappings, typeParameters[i]);
        }
        return resolvedArguments;
    } else {
        return null;
    }
}

private static Class<?> resolveTypeVariable(Class<?> type, Map<TypeVariable<Class<?>>, Type> mappedTypes, TypeVariable<Class<?>> variable) {
    if (mappedTypes.containsKey(variable)) {
        Type mappedType = mappedTypes.get(variable);
        if (mappedType instanceof Class<?>) {
            return (Class<?>) mappedType;
        } else if (mappedType instanceof ParameterizedType) {
            return resolveParameterizedType((ParameterizedType) mappedType);
        } else {
            throw new IllegalArgumentException("Unsupported type: " + type);
        }
    } else {
        return resolveTypeVariableFromSuperclass(type, mappedTypes, variable);
    }
}

