public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings result = new Mappings();
    for (String fieldName : mappings.keySet()) {
        if (fieldName.startsWith("_")) {
            continue;
        }
        Object field = mappings.get(fieldName);
        if (field instanceof ArrayNode) {
            ArrayNode arrayNode = (ArrayNode) field;
            for (int i = 0; i < arrayNode.size(); i++) {
                Object element = arrayNode.get(i);
                if (element instanceof ObjectNode) {
                    ObjectNode objNode = (ObjectNode) element;
                    for (String innerFieldName : objNode.keySet()) {
                        if (!mappings.containsKey(innerFieldName)) {
                            result.put(innerFieldName, objNode.get(innerFieldName));
                        }
                    }
                }
            }
        } else if (field instanceof ObjectNode) {
            ObjectNode objNode = (ObjectNode) field;
            for (String innerFieldName : objNode.keySet()) {
                if (!mappings.containsKey(innerFieldName)) {
                    result.put(innerFieldName, objNode.get(innerFieldName));
                }
            }
        } else {
            result.put(fieldName, field);
        }
    }
    return result;
}

