}

private void popType(final String descriptor) {
    final int arrayDepth = descriptor.getArrayDepth();
    final String elementDescriptor = descriptor.getElementType();
    for (int i = 0; i < arrayDepth; i++) {
        outputFrameStack.pop();
    }
    if (elementDescriptor.isPrimitive() || elementDescriptor.isVarArgs()) {
        return;
    } else if (elementDescriptor.isClass()) {
        outputFrameStack.pop();
    } else if (elementDescriptor.isInterface() || elementDescriptor.isArray()) {
        popType(elementDescriptor);
    }
}

private void popMethod(final String descriptor) {
    final int argumentCount = descriptor.getArgumentCount();
    final String returnType = descriptor.getReturnType();
    for (int i = 0; i < argumentCount; i++) {
        outputFrameStack.pop();
    }
    if (returnType.isVoid()) {
        return;
    } else if (returnType.isPrimitive()) {
        outputFrameStack.getLast().unhandledPrimitive();
    } else if (returnType.isVarArgs()) {
        outputFrameStack.getLast().unhandledVarArgs();
    } else {
        outputFrameStack.getLast().unhandledClass(returnType);
    }
}

void pop(String descriptor){
    if (isMethodDescriptor(descriptor)) {
        final String[] typeDescriptors = getArgumentTypeDescriptors(descriptor);
        for (String typeDescriptor : typeDescriptors) {
            pop(typeDescriptor);
        }
    } else {
        popType(descriptor);
    }
}

private void pop(final String descriptor) {
    int i = 0;
    while (i < descriptor.length()) {
        char currentChar = descriptor.charAt(i);
        if (currentChar == 'L') {
            // pop the entire object reference
            frameStack.pop();
        } else if (currentChar == '[') {
            // pop the contents of an array
            for (int j = 0; j < Frame.DEFAULT_ARRAY_SIZE; j++) {
                frameStack.pop();
            }
        } else if (currentChar == 'I' || currentChar == 'B' || currentChar == 'S' || currentChar == 'C' || currentChar == 'D' || currentChar == 'J' || currentChar == 'F' || currentChar == 'V') {
            // pop the primitive value
            frameStack.pop();
        } else {
            // invalid descriptor - throw.
            throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
        }
        i++;
    }
}

