    double x2 = cx + halfWidth;
    Box2D left = box.createFromSize(new Size2D(halfWidth, box.height()), new Point2D(x1, box.center().y()));
    Box2D right = box.createFromSize(new Size2D(halfWidth, box.height()), new Point2D(x2, box.center().y()));
    return Pair.of(left, right);
}

