private static byte getJVMSFormat(int type) {
  switch (type) {
    case Top:
      return new byte[] {0x00};
    case Integer:
      return new byte[] {0x01};
    case Float:
      return new byte[] {0x02};
    case Double:
      return new byte[] {0x03};
    case Long:
      return new byte[] {0x04};
    case Null:
      return new byte[] {0x05};
    case UninitializedThis:
      return new byte[] {0x06};
    case Object:
      return new byte[] {0x07, (byte) 0x00};
    case Uninitialized:
      return new byte[] {0x08, (byte) 0x00};
    default:
      throw new IllegalArgumentException("Invalid type: " + type);
  }
}

private void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        switch (getAbstractType(currentFrame[i])) {
            case OBJECT:
                stackMapTableEntries.add(new ObjectVariableInfo(getCpIndex(currentFrame[i]), 0));
                break;
            case UNINITIALIZED_THIS:
                stackMapTableEntries.add(new UninitializedThisVariableInfo());
                break;
            case UNINITIALIZED:
                stackMapTableEntries.add(new UninitializedVariableInfo(getOffset(currentFrame[i])));
                break;
            default:
                throw new VerificationError("Invalid abstract type: " + getAbstractType(currentFrame[i]));
        }
    }
}

