public int nextPrime(int desiredCapacity) {
    // First, check if the desired capacity is already a prime number
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // If not, find the next prime number which is just below or at
    // the desired capacity
    int potentialPrime = desiredCapacity;
    while (!isPrime(potentialPrime)) {
        potentialPrime++;
    }

    // If we hit the maximum prime number, return the maximum prime number
    if (potentialPrime == Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }

    return potentialPrime;
}

private static boolean isPrime(int n) {
    // Check if n is a prime number
    if (n <= 1) {
        return false;
    } else if (n == 2 || n == 3) {
        return true;
    }

    // Check if n is divisible by 2 to n-1
    for (int i = 2; i < n; i++) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}

