public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuffer buf = new StringBuffer(str.length());
    for (int i = 0; i < str.length(); ) {
        int ch = str.charAt(i);
        if (ch == '\\' || ch == '\'') {
            if (i < str.length() - 1) {
                i++;
                ch = str.charAt(i);
                switch (ch) {
                    case 'b':
                        buf.append('\b');
                        break;
                    case 't':
                        buf.append('\t');
                        break;
                    case 'n':
                        buf.append('\n');
                        break;
                    case 'f':
                        buf.append('\f');
                        break;
                    case 'r':
                        buf.append('\r');
                        break;
                    case 'u':
                        if (i + 4 < str.length()) {
                            String code = str.substring(i + 1, i + 5);
                            i += 4;
                            try {
                                buf.append((char) Integer.parseInt(code, 16));
                            } catch (NumberFormatException e) {
                                throw new Exception("Invalid unicode code point in " + str + ": " + code, e);
                            }
                        } else {
                            buf.append(ch);
                        }
                        break;
                    default:
                        buf.append(ch);
                }
            } else {
                buf.append('\\');
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

