public static String unescapeJava(String str) throws Exception {
    // Escape Sequences
    String escapeSequences = "\"'\\b\f\n\r\t";

    // String Buffer
    StringBuffer sb = new StringBuffer();

    // Loop through each character in the string
    for (int i = 0; i < str.length(); i++) {
        // Check if the current character is an escape character
        if (str.charAt(i) == '\\') {
            // If the next character is an escape sequence character, unescape it
            i++;
            char c = str.charAt(i);
            if (escapeSequences.indexOf(c) != -1) {
                // Append the unescaped character to the string buffer
                sb.append(c);
            } else {
                // If the escape sequence is not recognized, throw an exception
                throw new Exception("Invalid escape sequence: \\" + c);
            }
        } else {
            // If the current character is not an escape character, just append it to the string buffer
            sb.append(str.charAt(i));
        }
    }

    // Return the unescaped string
    return sb.toString();
}

