public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    if (byteArrayValue != null) {
        if (byteArrayValue.length - byteOffset <= 0) {
            throw new IndexOutOfBoundsException("The specified offset " + byteOffset + " is outside the bounds of the array");
        }
        if (byteLength < 0) {
            throw new IndexOutOfBoundsException("The specified length " + byteLength + " is negative");
        }
        if (byteLength > byteArrayValue.length - byteOffset) {
            throw new IndexOutOfBoundsException("The requested length is greater than the size available in the array");
        }
        // Increase the capacity of the byte vector if necessary
        if (byteLength > currentCapacity) {
            ensureCapacity(byteLength);
        }
        // Write the byte array to the byte vector
        System.arraycopy(byteArrayValue, byteOffset, buf, count, byteLength);
        count += byteLength;
    } else {
        if (byteLength > 0) {
            // Increase the capacity of the byte vector if necessary
            if (byteLength > currentCapacity) {
                ensureCapacity(byteLength);
            }
            // Write nullbytes to the byte vector
            for (int i = 0; i < byteLength; i++) {
                buf[count++] = 0;
            }
        }
    }
    return this;
}

