int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new NullPointerException("Name and descriptor must not be null");
    }
    // Remove unnecessary characters in the descriptor
    String cleanDescriptor = descriptor.replaceAll("\\[", "").replaceAll("\\)", "")
                                       .replaceAll("\\(", "L").replaceAll(";", "");
    String matchingConstant = constantPool.get(cleanDescriptor + ";");
    if(matchingConstant != null){
        // Return existing constant
        return matchingConstant;
    }
    // Add new constant to the pool
    int newConstant = constantPool.size() + 1;
    constantPool.add(cleanDescriptor + ";");
    return newConstant;
}

