public static int addConstantNameAndType(String name, String descriptor){

   if(constantPool.contains(name, descriptor)) return constantPool.indexOf(name, descriptor);

   int nameAndTypeIndex = constantPool.indexOf(name, descriptor);

   if(nameAndTypeIndex == -1){
    ConstantValueEntry constantNameAndType = new ConstantValueEntry();
    constantNameAndType.setTag(SymbolTable.CONSTANT_NAMEANDTYPE);
    constantNameAndType.setStringName(name);
    constantNameAndType.setStringType(descriptor);
    nameAndTypeIndex = constantPool.add(constantNameAndType);
   }

  return nameAndTypeIndex;
}

int addConstantNameAndType(final String name, final String descriptor) {

    // Check if the constant pool already contains a similar item
    if (constantPool.containsKey(name + descriptor)) {
        return constantPool.get(name + descriptor);
    }

    // Otherwise, create a new Symbol with the given value
    Symbol symbol = new Symbol(name, descriptor);
    constantPool.put(name + descriptor, symbol);
    return symbol.getID();
}

