private void compactBuckets(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // IF bucketsByLabel IS null OR labels IS null OR minLabel IS less than 0 THEN throw a NullPointerException
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new NullPointerException("Buckets or labels cannot be null. Min label must be a positive integer.");
    }

    // IF bucketsByLabel has no elements OR labels has no elements THEN return
    if (bucketsByLabel.isEmpty() || labels.isEmpty()) {
        return;
    }

    // CONCAT unique labels into a set OF integers
    Set<Integer> uniqueLabels = new HashSet<>();
    uniqueLabels.addAll(labels);

    // ITERATE OVER uniqueLabels
    for (Integer label : uniqueLabels) {
        // IF label IS equal to minLabel THEN continue
        if (label.equals(minLabel)) {
            continue;
        }

        // ITERATE OVER bucketsByLabel
        for (Set<Integer> bucket : bucketsByLabel) {
            // IF bucket IS not empty AND bucket HAS label THEN move bucket to the bucket with label 0
            if (!bucket.isEmpty() && bucket.contains(label)) {
                bucketsByLabel.get(0).addAll(bucket);
                bucket.clear();
            }
        }

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from bucket with label minLabel to bucket with label 0
    Set<Integer> movedVertices = bucketsByLabel.get(minLabel);
    bucketsByLabel.get(0).addAll(movedVertices);
    movedVertices.clear();

    // Clear the bucket with label minLabel
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling accordingly
    for (Integer v : labels) {
        int label = labels.indexOf(v);
        if (label > 0) {
            labels.set(v, label - 1);
        }
    }
}

