private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with label 'minLabel'
    Set<Integer> minBucket = null;
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).contains(minLabel)) {
            minBucket = bucketsByLabel.get(i);
            break;
        }
    }

    // Move all vertices from 'minBucket' to the bucket with label '0'
    for (Integer vertex : minBucket) {
        int vertexLabel = labels.get(vertex);
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
    }

    // Clear the bucket with label 'minLabel'
    minBucket.clear();
}

