private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
  if (bounds == null || bounds.isEmpty()) {
    return null;
  }
  List<Integer> suffixSum = new ArrayList<>();
  Long sum = 0L;
  for (Integer bound : bounds) {
    if (bound < 0) {
      throw new IllegalArgumentException("Input bounds cannot be negative");
    }
    suffixSum.add(suffixSum.isEmpty() ? bound : suffixSum.get(suffixSum.size() - 1) + bound);
    sum += bound;
  }
  return new Pair<>(suffixSum, sum);
}

