public void abbreviate(final int nameStart, final StringBuffer buf){
    final String name = getString().substring(nameStart);
    final int nameLength = name.length();
    if (nameLength > 0 && name.charAt(0) == ':') {
        buf.append(name.substring(1));
        return;
    }
    final int lastDot = name.lastIndexOf('.');
    int lastIdx = lastDot < 0 ? 0 : lastDot + 1;
    int idx = lastIdx;
    while (idx < nameLength) {
        final char ch = name.charAt(idx);
        if (ch == '[') {
            buf.append(ch);
            int depth = 0;
            while (idx < nameLength) {
                ch = name.charAt(nameStart);
                if (ch == '[') {
                    depth++;
                } else if (ch == ']') {
                    depth--;
                } else if (depth == 0 && (ch == '.' || ch == ';')) {
                    break;
                }
                idx++;
            }
            buf.append(ch);
        } else {
            idx++;
        }
    }
}

