        // Check if the current character is a '{' or '}'
        if (s.charAt(i) == '{' || s.charAt(i) == '}') {
            // If it is, replace it with the corresponding percent-encoded character
            encodedString += "%" + Integer.toHexString(s.charAt(i));
        } else {
            // If it is not, include it in the encoded string as-is
            encodedString += s.charAt(i);
        }
    }
    // Return the encoded string
    return encodedString;
}

