public static int indexOfExtension(String filename) {

     // Check if the filename is null or empty
     if (filename == null || filename.isEmpty()) {
          return -1;
     }

     // Get the index of the last separator character
     int index = indexOfLastSeparator(filename);

     // If the index is not the last character in the string, return -1
     if (index != filename.length() - 1) {
          return -1;
     }

     // Otherwise, return the index of the last separator character
     return index;
}

public static int indexOfLastSeparator(String filename) {

     // Check if the filename is null or empty
     if (filename == null || filename.isEmpty()) {
          return -1;
     }

     // Get the index of the last directory separator character in the filename
     int index = filename.lastIndexOf(File.separatorChar);

     // If the separator character is not found, return -1
     if (index == -1) {
          return -1;
     }

     // Otherwise, return the index of the last separator character
     return index;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastUnixSep = indexOfLastSeparator(filename);
    int lastWindowsSep = filename.lastIndexOf("\\");
    int lastSep = Math.max(lastUnixSep, lastWindowsSep);

    int extensionPos = filename.lastIndexOf(".", lastSep);
    return extensionPos;
}

