public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Check for null or insufficient length of substring
    if (substring == null || str.length() - index < substring.length()) {
        return false;
    }

    // Check for matching characters at the given index
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    // All characters match, so the substring matches
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index >= str.length()) {
        return false;
    }

    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

public boolean substringMatch(String str, int index, String substring) {
    if (str == null || substring == null) {
        return false;
    }

    int strLen = str.length();
    int subStrLen = substring.length();

    if (index < 0 || index + subStrLen > strLen) {
        return false;
    }

    for (int i = 0; i < subStrLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

